  FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE ON UPDATE NO ACTION
);

CREATE TABLE "locations" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "project_id" uuid NOT NULL,
  "name" text NOT NULL,
  "description" text DEFAULT ''::text,
  "atmosphere" text DEFAULT ''::text,
  "history" text DEFAULT ''::text,
  "sensory_details" text DEFAULT ''::text,
  "sort_order" integer DEFAULT 0,
  "created_at" timestamp without time zone DEFAULT now() NOT NULL,
  "linked_character_ids" jsonb DEFAULT '[]'::jsonb,
  "always_in_context" boolean DEFAULT true,
  "updated_at" timestamp without time zone DEFAULT now() NOT NULL,
  "embedding" vector(1536),
  PRIMARY KEY ("id"),
  FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE ON UPDATE NO ACTION
);

CREATE TABLE "plot_threads" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "project_id" uuid NOT NULL,
  "name" text NOT NULL,
  "description" text DEFAULT ''::text,
  "status" character varying(20) DEFAULT 'Active'::character varying,
  "stakes" text DEFAULT ''::text,
  "connections" text DEFAULT ''::text,
  "sort_order" integer DEFAULT 0,
  "created_at" timestamp without time zone DEFAULT now() NOT NULL,
  "always_in_context" boolean DEFAULT true,
  "last_mentioned_chapter_id" uuid,
  "starvation_warning" boolean DEFAULT false,
  "updated_at" timestamp without time zone DEFAULT now() NOT NULL,
  PRIMARY KEY ("id"),
  FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE ON UPDATE NO ACTION
);

CREATE TABLE "production_shots" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "project_id" uuid NOT NULL,
  "chapter_id" uuid,
  "scene_number" integer DEFAULT 1 NOT NULL,
  "shot_number" integer DEFAULT 1 NOT NULL,
  "shot_type" text DEFAULT 'Medium shot'::text,
  "camera_movement" text DEFAULT 'Static'::text,
  "lighting_mood" text DEFAULT 'Golden hour'::text,
  "time_of_day" text DEFAULT 'Afternoon'::text,
  "subject" text DEFAULT ''::text,
  "action" text DEFAULT ''::text,
  "location" text DEFAULT ''::text,
  "mood" text DEFAULT ''::text,
  "primary_character_id" uuid,
  "soul_prompt" text DEFAULT ''::text,
  "video_prompt" text DEFAULT ''::text,
  "dialogue" text DEFAULT ''::text,
  "speaker" text DEFAULT ''::text,
  "preview_image_url" text DEFAULT ''::text,
  "animated_video_url" text DEFAULT ''::text,
  "final_video_url" text DEFAULT ''::text,
  "generation_status" character varying(30) DEFAULT 'idle'::character varying,
  "higgsfield_job_id" text DEFAULT ''::text,
  "sort_order" integer DEFAULT 0,
  "created_at" timestamp without time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp without time zone DEFAULT now() NOT NULL,
  "camera_preset" text DEFAULT ''::text,
  "viral_preset" text DEFAULT ''::text,
  "character_emotion" text DEFAULT ''::text,
  "focal_length" text DEFAULT ''::text,
  "duration" integer DEFAULT 5,
  "aspect_ratio" text DEFAULT '16:9'::text,
  "generated_video_url" text DEFAULT ''::text,
  "multi_shot_script" text DEFAULT ''::text,
  "scene_final_video_url" text DEFAULT ''::text,
  "quality_score" real,
  "quality_weakest" character varying(30),
  "quality_note" text DEFAULT ''::text,
  "review_status" character varying(12) DEFAULT 'draft'::character varying NOT NULL,
  "candidate_preview_urls" jsonb DEFAULT '[]'::jsonb,
  "trim_start_sec" real,
  "trim_end_sec" real,
  "scene_audio_track_url" text DEFAULT ''::text,
  "generation_error" text DEFAULT ''::text,
  PRIMARY KEY ("id"),
  FOREIGN KEY ("chapter_id") REFERENCES "chapters" ("id") ON DELETE SET NULL ON UPDATE NO ACTION,
  FOREIGN KEY ("primary_character_id") REFERENCES "characters" ("id") ON DELETE SET NULL ON UPDATE NO ACTION,
  FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE ON UPDATE NO ACTION
);

CREATE TABLE "reader_reactions" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "session_id" uuid NOT NULL,
  "chapter_id" uuid NOT NULL,
  "text_offset" integer NOT NULL,
  "reaction_type" text NOT NULL,
  "created_at" timestamp without time zone DEFAULT now() NOT NULL,
  PRIMARY KEY ("id"),
  FOREIGN KEY ("chapter_id") REFERENCES "chapters" ("id") ON DELETE CASCADE ON UPDATE NO ACTION,
  FOREIGN KEY ("session_id") REFERENCES "reader_sessions" ("id") ON DELETE CASCADE ON UPDATE NO ACTION
);

CREATE TABLE "story_memories" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "project_id" uuid NOT NULL,
  "chapter_id" uuid,
  "fact" text NOT NULL,
  "category" character varying(30) DEFAULT 'general'::character varying,
  "auto_extracted" boolean DEFAULT true,
  "created_at" timestamp without time zone DEFAULT now() NOT NULL,
  "chapter_index" integer DEFAULT 0,
  "structured_data" jsonb,
  PRIMARY KEY ("id"),
  FOREIGN KEY ("chapter_id") REFERENCES "chapters" ("id") ON DELETE SET NULL ON UPDATE NO ACTION,
  FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE ON UPDATE NO ACTION
);

CREATE TABLE "story_promises" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "project_id" uuid NOT NULL,
  "thread_id" uuid,
  "setup" text NOT NULL,
  "setup_chapter_id" uuid,
  "payoff_intent" text DEFAULT ''::text,
  "payoff_chapter_id" uuid,
  "status" character varying(20) DEFAULT 'open'::character varying,
  "priority" character varying(5) DEFAULT 'B'::character varying,
  "created_at" timestamp without time zone DEFAULT now() NOT NULL,
  "embedding" vector(1536),
  PRIMARY KEY ("id"),
  FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE ON UPDATE NO ACTION,
  FOREIGN KEY ("thread_id") REFERENCES "story_threads" ("id") ON DELETE SET NULL ON UPDATE NO ACTION
);

CREATE TABLE "universe_characters" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "universe_id" uuid NOT NULL,
  "name" text NOT NULL,
  "base_profile" jsonb,
  "is_alive" boolean DEFAULT true,
  "created_at" timestamp without time zone DEFAULT now() NOT NULL,
  PRIMARY KEY ("id"),
  FOREIGN KEY ("universe_id") REFERENCES "universes" ("id") ON DELETE CASCADE ON UPDATE NO ACTION
);

CREATE TABLE "universe_events" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "universe_id" uuid NOT NULL,
  "project_id" uuid,
  "name" text NOT NULL,
  "description" text DEFAULT ''::text,
  "timeline_sort" integer NOT NULL,
  "is_canon" boolean DEFAULT true,
  "created_at" timestamp without time zone DEFAULT now() NOT NULL,
  PRIMARY KEY ("id"),
  FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE SET NULL ON UPDATE NO ACTION,
  FOREIGN KEY ("universe_id") REFERENCES "universes" ("id") ON DELETE CASCADE ON UPDATE NO ACTION
);

CREATE TABLE "character_evolution_log" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "project_id" uuid NOT NULL,
  "character_id" uuid NOT NULL,
  "chapter_index" integer NOT NULL,
  "trigger_memory_ids" text[] DEFAULT '{}'::text[] NOT NULL,
  "previous_state" jsonb DEFAULT '{}'::jsonb NOT NULL,
  "updated_traits" jsonb DEFAULT '{}'::jsonb NOT NULL,
  "evolution_summary" text DEFAULT ''::text NOT NULL,
  "created_at" timestamp without time zone DEFAULT now() NOT NULL,
  PRIMARY KEY ("id"),
  FOREIGN KEY ("character_id") REFERENCES "characters" ("id") ON DELETE CASCADE ON UPDATE NO ACTION,
  FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE ON UPDATE NO ACTION
);

CREATE TABLE "character_relationships" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "project_id" uuid NOT NULL,
  "character_a_id" uuid NOT NULL,
  "character_b_id" uuid NOT NULL,
  "trust_level" integer DEFAULT 50,
  "relationship_type" text DEFAULT ''::text,
  "four_horsemen" jsonb DEFAULT '{"contempt": 0, "criticism": 0, "stonewalling": 0, "defensiveness": 0}'::jsonb,
  "notes" text DEFAULT ''::text,
  "updated_at" timestamp without time zone DEFAULT now() NOT NULL,
  "power_differential" integer DEFAULT 0,
  "emotional_register" character varying(50) DEFAULT ''::character varying,
  "knowledge_asymmetry" text DEFAULT ''::text,
  "dependency_structure" character varying(50) DEFAULT 'none'::character varying,
  "attachment_style_a" character varying(30) DEFAULT ''::character varying,
  "arc_trajectory" character varying(30) DEFAULT ''::character varying,
  PRIMARY KEY ("id"),
  FOREIGN KEY ("character_a_id") REFERENCES "characters" ("id") ON DELETE CASCADE ON UPDATE NO ACTION,
  FOREIGN KEY ("character_b_id") REFERENCES "characters" ("id") ON DELETE CASCADE ON UPDATE NO ACTION,
  FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE ON UPDATE NO ACTION
);

CREATE TABLE "project_character_states" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "project_id" uuid NOT NULL,
  "universe_char_id" uuid NOT NULL,
  "knowledge_override" jsonb,
  "emotional_state" text,
  "state_notes" text,
  "is_deceased" boolean DEFAULT false,
  "created_at" timestamp without time zone DEFAULT now() NOT NULL,
  PRIMARY KEY ("id"),
  FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE ON UPDATE NO ACTION,
  FOREIGN KEY ("universe_char_id") REFERENCES "universe_characters" ("id") ON DELETE CASCADE ON UPDATE NO ACTION
);

-- Indexes (observed)
CREATE UNIQUE INDEX creator_bibles_project_id_unique ON public.creator_bibles USING btree (project_id);
CREATE UNIQUE INDEX email_verification_tokens_token_unique ON public.email_verification_tokens USING btree (token);
CREATE UNIQUE INDEX password_reset_tokens_token_unique ON public.password_reset_tokens USING btree (token);
CREATE UNIQUE INDEX reader_sessions_token_unique ON public.reader_sessions USING btree (token);
CREATE UNIQUE INDEX sessions_session_token_unique ON public.sessions USING btree (session_token);
CREATE UNIQUE INDEX showcases_project_id_unique ON public.showcases USING btree (project_id);
CREATE UNIQUE INDEX showcases_slug_unique ON public.showcases USING btree (slug);
CREATE UNIQUE INDEX subscriptions_user_id_unique ON public.subscriptions USING btree (user_id);
CREATE UNIQUE INDEX users_email_unique ON public.users USING btree (email);
